INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990038, 990038, '설정 > 알림에서 해당 유형이 꺼져 있으면 목록에 표시되지 않습니다. 토글을 확인해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(10, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(10, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990039, 990039, '기기 절전 모드가 켜져 있으면 위치 수집이 중단될 수 있습니다. 예외 앱으로 등록해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(9, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(9, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990040, 990040, '문의 주신 내용은 담당 부서에 전달했습니다. 처리되는 대로 다시 안내드리겠습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(8, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(8, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990041, 990041, '페어링 코드는 발급 후 유효시간이 지나면 자동 삭제됩니다. 코드 발급 화면을 다시 열어 새 코드로 시도해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(7, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(7, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990042, 990042, '결제 승인과 지갑 반영 사이에 최대 1분 정도 지연이 있을 수 있습니다. 그래도 반영되지 않으면 주문번호를 알려주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(6, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(6, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990043, 990043, '이체는 부모 지갑 잔액에서 빠져나갑니다. 충전 대기(READY) 상태 금액은 잔액에 포함되지 않습니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(5, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(5, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990044, 990044, '충전 내역 화면에서 해당 주문의 환불 버튼으로 신청하실 수 있습니다. 전액 환불만 지원합니다.', LOCALTIMESTAMP - NUMTODSINTERVAL(4, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(4, 'DAY'));
INSERT INTO inquiry_answer (id, inquiry_id, content, created_at, updated_at) VALUES (990045, 990045, '자녀 기기의 알림 권한과 화면 캡처 권한이 모두 켜져 있어야 합니다. 설정에서 확인해 주세요.', LOCALTIMESTAMP - NUMTODSINTERVAL(3, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(3, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990001, '키드핵 서비스 오픈 안내', '자녀 안심 관리 서비스 키드핵이 정식 오픈했습니다. 위치 확인, 앱 사용 관리, 용돈 관리 기능을 이용해 보세요.', 990001, LOCALTIMESTAMP + NUMTODSINTERVAL(1979882, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979882, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990002, '개인정보 처리방침 개정 안내', '위치정보 보관 기간이 명확해졌습니다. 자세한 내용은 첨부된 문서를 확인해 주세요.', 990002, LOCALTIMESTAMP + NUMTODSINTERVAL(1979884, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979884, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990003, '루키즈페이 카드 등록 기능 오픈', '이제 앱에서 카드를 등록해 바로 충전할 수 있습니다.', 990001, LOCALTIMESTAMP + NUMTODSINTERVAL(1979886, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979886, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990004, '자녀 채팅 기능 추가 안내', '부모와 자녀가 앱 안에서 바로 대화할 수 있습니다.', 990002, LOCALTIMESTAMP + NUMTODSINTERVAL(1979888, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979888, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990005, '스크린타임 한도 알림 추가', '자녀의 하루 사용 한도에 도달하면 부모에게 알림이 갑니다.', 990001, LOCALTIMESTAMP + NUMTODSINTERVAL(1979890, 'DAY'), LOCALTIMESTAMP + NUMTODSINTERVAL(1979890, 'DAY'));
INSERT INTO notice (id, title, content, author_id, created_at, updated_at) VALUES (990006, '앱 v1.2.0 업데이트 안내', '이번 업데이트에서 스마트폰 사용시간 관련 문제를 수정했습니다. 스토어에서 최신 버전으로 갱신해 주세요.', 990002, LOCALTIMESTAMP - NUMTODSINTERVAL(1, 'DAY'), LOCALTIMESTAMP - NUMTODSINTERVAL(1, 'DAY'));
